--
-- Name: updatetutoralumno(integer, character varying, character varying, character varying, character varying, character varying, character varying, character varying, character varying, bytea, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.updatetutoralumno(pidtutor integer, ptutornombre character varying, ptapellidop character varying, ptapellidom character varying, pttelefono character varying, panombre character varying, paapellidop character varying, paapellidom character varying, patelefono character varying, pafoto bytea, pafechapago date) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
UPDATE TUTOR SET Nombre = ptutornombre,apellidop = ptapellidop, apellidom = ptapellidom, telefono = pttelefono where idtutor = Pidtutor;
UPDATE alumno SET Nombre = panombre, apellidop = paapellidop, apellidom = paapellidom, telefono = patelefono, foto = pafoto, fechapago = pafechapago where idtutorfk = Pidtutor;
END;
$$;


