--
-- Name: alumnost; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.alumnost AS
 SELECT idalumno,
    nombre,
    apellidop,
    apellidom,
    telefono,
    foto,
    fechapago
   FROM public.alumno
  WHERE (idtutorfk = 0);


ALTER VIEW public.alumnost OWNER TO postgres;

--
-- Name: tutor; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.tutor (
    idtutor integer NOT NULL,
    nombre character varying(50) NOT NULL,
    apellidop character varying(50) NOT NULL,
    apellidom character varying(50) DEFAULT 'None'::character varying,
    telefono character varying(10) NOT NULL
);


ALTER TABLE public.tutor OWNER TO postgres;

--
-- Name: alumnot; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.alumnot AS
 SELECT alumno.idalumno,
    alumno.nombre AS nombrea,
    alumno.apellidop AS apellidopa,
    alumno.apellidom AS apellidoma,
    alumno.telefono AS telefonoa,
    alumno.foto,
    alumno.fechapago,
    tutor.idtutor,
    tutor.nombre,
    tutor.apellidop,
    tutor.apellidom,
    tutor.telefono
   FROM (public.alumno
     JOIN public.tutor ON ((alumno.idtutorfk = tutor.idtutor)));


